begin;
create or replace function public.add_group_owner() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.group_members(group_id,user_id,role) values(new.id,new.owner_id,'owner');return new;end$$;
create trigger group_owner_membership after insert on public.groups for each row execute function public.add_group_owner();
create or replace function public.join_group_by_code(p_code text) returns uuid language plpgsql security definer set search_path='' as $$declare g uuid;begin select id into g from public.groups where join_code=p_code; if g is null then raise exception 'Invalid group code';end if;insert into public.group_members(group_id,user_id,role) values(g,auth.uid(),'member') on conflict do nothing;return g;end$$;
create or replace function public.group_leaderboard(p_group uuid,p_from timestamptz,p_to timestamptz) returns table(user_id uuid,timer_seconds bigint,manual_seconds bigint,active_days bigint) language sql stable security definer set search_path='' as $$select s.owner_id,coalesce(sum(s.duration_seconds) filter(where s.source='TIMER'),0)::bigint,coalesce(sum(s.duration_seconds) filter(where s.source='MANUAL'),0)::bigint,count(distinct (s.started_at at time zone 'UTC')::date)::bigint from public.study_sessions s join public.group_members gm on gm.user_id=s.owner_id where gm.group_id=p_group and public.is_group_member(p_group) and s.status='COMPLETED' and s.started_at>=p_from and s.started_at<p_to and s.deleted_at is null group by s.owner_id order by 2 desc$$;
create or replace function public.delete_my_account() returns void language plpgsql security definer set search_path='' as $$begin delete from auth.users where id=auth.uid();end$$;
revoke all on function public.join_group_by_code(text) from public;grant execute on function public.join_group_by_code(text) to authenticated;
revoke all on function public.group_leaderboard(uuid,timestamptz,timestamptz) from public;grant execute on function public.group_leaderboard(uuid,timestamptz,timestamptz) to authenticated;
revoke all on function public.delete_my_account() from public;grant execute on function public.delete_my_account() to authenticated;
commit;
